/*
 * NEW YEAR 05 — NEW YEAR RIBBON TYPOGRAPHY
 * Pure Canvas 2D. Original vector lettering; no fonts or external assets.
 * One continuous 20-second scene, with a seamless deterministic loop.
 * Host video export: 3840 x 2160, 60 fps, 100,000,000 bps minimum.
 * Bitrate is an encoder setting; this function renders the artwork only.
 */

function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (sceneProgress + currentScene);
  const C = {
    navy: '#172442',
    ivory: '#FFF7E6',
    paper: '#EADCC2',
    gold: '#E9B454',
    paleGold: '#F9D78C',
    amber: '#BE7E36',
    coral: '#E97870',
    deepCoral: '#BC555D'
  };
  const smooth = (a, b, v) => {
    const q = Math.max(0, Math.min(1, (v - a) / (b - a)));
    return q * q * q * (q * (q * 6 - 15) + 10);
  };
  // Related objects share these clocks. Every endpoint has matching velocity.
  const edgeTravel = smooth(0, 5, loopT) * (1 - smooth(15, 20, loopT));
  const ribbonOpen = smooth(5, 10, loopT) * (1 - smooth(15, 20, loopT));
  const cornerEmphasis = smooth(10, 12, loopT) * (1 - smooth(16, 19, loopT));
  const breath = Math.sin(phase * 2);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent';
  ctx.filter = 'none';
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function line(x1, y1, x2, y2, color, weight) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = weight;
    ctx.stroke();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p[0], p[1]);
      else ctx.lineTo(p[0], p[1]);
    });
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function star(x, y, radius, inner, points, angle, color) {
    const vertices = [];
    for (let i = 0; i < points * 2; i++) {
      const a = angle + i * Math.PI / points;
      const r = i % 2 === 0 ? radius : inner;
      vertices.push([x + Math.cos(a) * r, y + Math.sin(a) * r]);
    }
    polygon(vertices, color);
  }

  // A cubic centerline, with an analytic normal, keeps ribbon width constant.
  function ribbonPoint(p, reach, endY, controlY) {
    const q = 1 - p;
    const c = reach * 0.72;
    const x = -reach * q * q * q - 3 * c * q * q * p
      + 3 * c * q * p * p + reach * p * p * p;
    const y = endY * (q * q * q + p * p * p)
      + 3 * controlY * (q * q * p + q * p * p);
    const dx = 3 * (reach - c) * (q * q + p * p) + 12 * c * q * p;
    const dy = 3 * (controlY - endY) * q * q
      + 3 * (endY - controlY) * p * p;
    const length = Math.sqrt(dx * dx + dy * dy);
    return {x, y, tx: dx / length, ty: dy / length,
      nx: -dy / length, ny: dx / length};
  }

  function ribbon(reach, endY, controlY, bandWidth) {
    const samples = 80;
    const half = bandWidth * 0.5;
    const edge = (p, d) => {
      const a = ribbonPoint(p, reach, endY, controlY);
      return [a.x + a.nx * d, a.y + a.ny * d];
    };
    const vertices = [];
    for (let i = 0; i <= samples; i++) vertices.push(edge(i / samples, half));
    const end = ribbonPoint(1, reach, endY, controlY);
    vertices.push([end.x - end.tx * 15, end.y - end.ty * 15]);
    for (let i = samples; i >= 0; i--) vertices.push(edge(i / samples, -half));
    const start = ribbonPoint(0, reach, endY, controlY);
    vertices.push([start.x + start.tx * 15, start.y + start.ty * 15]);
    polygon(vertices, C.gold);
    ctx.strokeStyle = C.navy;
    ctx.lineWidth = 2.5;
    ctx.stroke();
    // Solid printed stripes, inset from both edges and notched ends.
    for (const stripe of [{offset: -bandWidth * 0.24, color: C.amber, weight: 3},
      {offset: bandWidth * 0.23, color: C.paleGold, weight: 3}]) {
      ctx.beginPath();
      for (let i = 0; i <= samples; i++) {
        const p = 0.035 + 0.93 * i / samples;
        const v = edge(p, stripe.offset);
        if (i === 0) ctx.moveTo(v[0], v[1]);
        else ctx.lineTo(v[0], v[1]);
      }
      ctx.strokeStyle = stripe.color;
      ctx.lineWidth = stripe.weight;
      ctx.stroke();
    }
  }

  const upperEndY = -111 + 2 * breath;
  const upperControlY = -443 + 2 * breath - 4 * ribbonOpen;
  const lowerEndY = 137 + 2 * breath;
  const lowerControlY = 285 + 2 * breath + 3 * ribbonOpen;
  ribbon(691 + 24 * ribbonOpen, upperEndY, upperControlY, 34);
  ribbon(701 + 24 * ribbonOpen, lowerEndY, lowerControlY, 31);

  // Glyphs use a shared unit grid. Counters are cut with the even-odd rule.
  const widths = {H: 0.72, A: 0.80, P: 0.70, Y: 0.76,
    N: 0.75, E: 0.65, W: 1.08, R: 0.75};

  function glyphPath(letter) {
    ctx.beginPath();
    switch (letter) {
      case 'H':
        ctx.moveTo(0, 0); ctx.lineTo(0.20, 0); ctx.lineTo(0.20, 0.40);
        ctx.lineTo(0.52, 0.40); ctx.lineTo(0.52, 0); ctx.lineTo(0.72, 0);
        ctx.lineTo(0.72, 1); ctx.lineTo(0.52, 1); ctx.lineTo(0.52, 0.60);
        ctx.lineTo(0.20, 0.60); ctx.lineTo(0.20, 1); ctx.lineTo(0, 1);
        ctx.closePath(); break;
      case 'A':
        ctx.moveTo(0.29, 0); ctx.lineTo(0.51, 0); ctx.lineTo(0.80, 1);
        ctx.lineTo(0.58, 1); ctx.lineTo(0.52, 0.78); ctx.lineTo(0.28, 0.78);
        ctx.lineTo(0.22, 1); ctx.lineTo(0, 1); ctx.closePath();
        ctx.moveTo(0.305, 0.61); ctx.lineTo(0.495, 0.61);
        ctx.lineTo(0.40, 0.26); ctx.closePath(); break;
      case 'P':
      case 'R':
        ctx.moveTo(0, 1); ctx.lineTo(0, 0); ctx.lineTo(0.39, 0);
        ctx.bezierCurveTo(0.60, 0, 0.70, 0.10, 0.70, 0.29);
        ctx.bezierCurveTo(0.70, 0.44, 0.63, 0.54, 0.49, 0.58);
        if (letter === 'R') {
          ctx.lineTo(0.75, 1); ctx.lineTo(0.51, 1);
          ctx.lineTo(0.27, 0.60);
        } else ctx.lineTo(0.39, 0.60);
        ctx.lineTo(0.20, 0.60); ctx.lineTo(0.20, 1); ctx.closePath();
        ctx.moveTo(0.20, 0.19); ctx.lineTo(0.37, 0.19);
        ctx.bezierCurveTo(0.46, 0.19, 0.50, 0.22, 0.50, 0.30);
        ctx.bezierCurveTo(0.50, 0.38, 0.46, 0.41, 0.37, 0.41);
        ctx.lineTo(0.20, 0.41); ctx.closePath(); break;
      case 'Y':
        ctx.moveTo(0, 0); ctx.lineTo(0.23, 0); ctx.lineTo(0.38, 0.36);
        ctx.lineTo(0.53, 0); ctx.lineTo(0.76, 0); ctx.lineTo(0.48, 0.58);
        ctx.lineTo(0.48, 1); ctx.lineTo(0.28, 1); ctx.lineTo(0.28, 0.58);
        ctx.closePath(); break;
      case 'N':
        ctx.moveTo(0, 1); ctx.lineTo(0, 0); ctx.lineTo(0.20, 0);
        ctx.lineTo(0.55, 0.61); ctx.lineTo(0.55, 0); ctx.lineTo(0.75, 0);
        ctx.lineTo(0.75, 1); ctx.lineTo(0.55, 1); ctx.lineTo(0.20, 0.39);
        ctx.lineTo(0.20, 1); ctx.closePath(); break;
      case 'E':
        ctx.moveTo(0, 0); ctx.lineTo(0.65, 0); ctx.lineTo(0.65, 0.19);
        ctx.lineTo(0.20, 0.19); ctx.lineTo(0.20, 0.40);
        ctx.lineTo(0.57, 0.40); ctx.lineTo(0.57, 0.59);
        ctx.lineTo(0.20, 0.59); ctx.lineTo(0.20, 0.81);
        ctx.lineTo(0.65, 0.81); ctx.lineTo(0.65, 1); ctx.lineTo(0, 1);
        ctx.closePath(); break;
      case 'W':
        ctx.moveTo(0, 0); ctx.lineTo(0.21, 0); ctx.lineTo(0.34, 0.66);
        ctx.lineTo(0.46, 0.13); ctx.lineTo(0.62, 0.13);
        ctx.lineTo(0.74, 0.66); ctx.lineTo(0.87, 0); ctx.lineTo(1.08, 0);
        ctx.lineTo(0.86, 1); ctx.lineTo(0.65, 1); ctx.lineTo(0.54, 0.51);
        ctx.lineTo(0.43, 1); ctx.lineTo(0.22, 1); ctx.closePath(); break;
    }
  }

  function letter(letter, x, y, size, face, ink) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(size, size);
    ctx.lineWidth = 7 / size;
    ctx.save();
    ctx.translate(5 / size, 7 / size);
    glyphPath(letter);
    ctx.fillStyle = C.navy;
    ctx.fill('evenodd');
    ctx.strokeStyle = C.navy;
    ctx.stroke();
    ctx.restore();
    glyphPath(letter);
    ctx.fillStyle = face;
    ctx.fill('evenodd');
    ctx.strokeStyle = C.navy;
    ctx.stroke();

    // A short solid inlay follows the same safe, inset route on each glyph.
    // Its length and the letter silhouette stay fixed throughout the cycle.
    ctx.save();
    ctx.clip('evenodd');
    let x1 = 0.10, y1 = 0.17, x2 = 0.10, y2 = 0.83;
    if (letter === 'A') { x1 = 0.36; y1 = 0.16; x2 = 0.15; y2 = 0.86; }
    if (letter === 'Y') { x1 = 0.15; y1 = 0.12; x2 = 0.31; y2 = 0.46; }
    if (letter === 'W') { x1 = 0.13; y1 = 0.13; x2 = 0.27; y2 = 0.85; }
    const start = 0.10 + 0.57 * edgeTravel;
    const end = start + 0.19;
    line(x1 + (x2 - x1) * start, y1 + (y2 - y1) * start,
      x1 + (x2 - x1) * end, y1 + (y2 - y1) * end, ink, 3 / size);
    ctx.restore();
    ctx.restore();
  }

  function wordWidth(value, size, tracking, wordGap) {
    let result = 0;
    for (let i = 0; i < value.length; i++) {
      result += value[i] === ' ' ? wordGap : widths[value[i]] * size;
      if (i + 1 < value.length && value[i] !== ' ' && value[i + 1] !== ' ')
        result += tracking;
    }
    return result;
  }

  function title(value, y, size, tracking, wordGap, face, ink) {
    let x = -wordWidth(value, size, tracking, wordGap) * 0.5 - 2.5;
    for (let i = 0; i < value.length; i++) {
      const c = value[i];
      if (c === ' ') { x += wordGap; continue; }
      letter(c, x, y, size, face, ink);
      x += widths[c] * size;
      if (i + 1 < value.length && value[i + 1] !== ' ') x += tracking;
    }
  }

  title('HAPPY', -239, 146, 22, 0, C.coral, C.navy);
  title('NEW YEAR', -43, 178, 21, 81, C.ivory, C.gold);

  // Divider accents occupy their own corridor between the two text rows.
  const ruleLength = 71 + 22 * edgeTravel;
  for (let side = -1; side <= 1; side += 2) {
    line(side * 357, -66, side * (357 + ruleLength), -66, C.gold, 3.5);
    circle(side * (357 + ruleLength + 13), -66, 2.8, C.coral);
  }
  polygon([[0, -72], [6, -66], [0, -60], [-6, -66]], C.gold);

  // Four fixed-size stars follow separate, mirrored corner orbits.
  // The orbit radii are small; the full travel stays clear of text and ribbons.
  const orbit = phase + 0.18 * Math.sin(phase);
  const orbitX = 10 + 4 * cornerEmphasis;
  const orbitY = 6 + 3 * cornerEmphasis;
  for (let side = -1; side <= 1; side += 2) {
    const dx = orbitX * Math.sin(orbit);
    const dy = orbitY * Math.cos(orbit);
    star(side * (778 + dx), -274 + dy, 25, 8.5, 4,
      -Math.PI / 2 + side * 0.045 * Math.sin(orbit), C.ivory);
    star(side * (767 + dx * 0.8), 260 - dy, 21, 7.5, 4,
      -Math.PI / 2 - side * 0.04 * Math.sin(orbit), C.coral);
    circle(side * (831 + dx * 0.30), -159 + dy * 0.5, 6, C.coral);
    circle(side * (826 + dx * 0.30), 158 - dy * 0.5, 5.5, C.ivory);
    const markX = side * (691 + dx * 0.4);
    const markY = -303 + dy * 0.5;
    line(markX - side * 7, markY - 8, markX + side * 7, markY + 8,
      C.coral, 4);
    const lowX = side * (659 + dx * 0.4);
    const lowY = 336 - dy * 0.5;
    line(lowX - side * 10, lowY + 3.5, lowX + side * 10, lowY - 3.5,
      C.gold, 4);
  }

  // The medal is physically attached to the lower ribbon midpoint.
  const ribbonMidY = lowerEndY * 0.25 + lowerControlY * 0.75;
  const medalY = ribbonMidY + 77;
  ctx.save();
  ctx.translate(0, medalY - 77);
  ctx.rotate(0.018 * breath);
  ctx.translate(0, 77);
  polygon([[-29, 20], [-5, 28], [-18, 72], [-29, 61], [-45, 66]], C.navy);
  polygon([[5, 28], [29, 20], [45, 66], [29, 61], [18, 72]], C.navy);
  polygon([[-27, 26], [-10, 31], [-20, 62], [-29, 55], [-37, 59]], C.coral);
  polygon([[10, 31], [27, 26], [37, 59], [29, 55], [20, 62]], C.coral);
  line(0, -77, 0, -37, C.navy, 15);
  line(0, -75, 0, -40, C.gold, 7);
  circle(0, 0, 47, C.navy);
  circle(0, 0, 42, C.gold);
  circle(0, 0, 34, C.paleGold);
  circle(0, 0, 29, C.navy);
  star(0, 0, 19, 8.2, 5, -Math.PI / 2, C.ivory);
  circle(-34, 0, 2.3, C.amber);
  circle(34, 0, 2.3, C.amber);
  ctx.restore();

  // A small typographic-free footer repeats the main palette with clean spacing.
  line(-146, 446, -50, 446, C.navy, 4);
  line(50, 446, 146, 446, C.navy, 4);
  star(0, 446, 11, 4, 4, -Math.PI / 2, C.gold);
  circle(-30, 446, 3, C.coral);
  circle(30, 446, 3, C.coral);
  ctx.restore();
}

/*
 * NEW YEAR 03 — GOLDEN MIDNIGHT TOAST
 * Pure Canvas 2D, no assets, no dependencies, no glow.
 * One 20-second scene; two measured toast cycles; seamless loop.
 * Host export preset: 3840x2160, 60 fps, 100,000,000 bps minimum.
 * The drawing function does not configure the host video encoder.
 *
 * FIREWORK / FIRECRACKER ORNAMENT SYSTEM (structured + proportional)
 *  1. One 10 s clock (= one toast cycle); every effect starts and ends
 *     inside it, so the 20 s loop is seamless.
 *  2. Each ornament is a firework with one size value. Burst radius,
 *     particle count, streak width, gravity droop, rocket thickness,
 *     crackle size and life time are all derived from that size.
 *  3. Sequence: rocket rises while the glasses approach, bursts exactly at
 *     the clink, sparks expand and droop, then small crackle pops
 *     (petasan) snap around the burst until it fades out.
 *  4. Bursts ripple outward from the centre: 0.9 ms of delay per px.
 *  5. Left and right fireworks are exact mirrors (same heights, same
 *     particles, mirrored x).
 */

function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const C = {
    navy: '#172442',
    blue: '#294B91',
    deepBlue: '#213661',
    ivory: '#FFF7E6',
    paper: '#F4E7CB',
    gold: '#E9B454',
    paleGold: '#F9D78C',
    amber: '#D99443',
    coral: '#E97870',
    mauve: '#AC78A8',
    glass: '#DEE7F7'
  };
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (a, b, v) => {
    const q = clamp((v - a) / (b - a));
    return q * q * q * (q * (q * 6 - 15) + 10);
  };

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent';
  ctx.filter = 'none';
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function rounded(x, y, w, h, radius, color, stroke, lineWidth) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (color) { ctx.fillStyle = color; ctx.fill(); }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = lineWidth || 3;
      ctx.stroke();
    }
  }

  function ellipse(x, y, rx, ry, color, stroke, lineWidth) {
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (color) { ctx.fillStyle = color; ctx.fill(); }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = lineWidth || 3;
      ctx.stroke();
    }
  }

  function line(x1, y1, x2, y2, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function star(x, y, radius, inner, points, angle, color) {
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const a = angle + i * Math.PI / points;
      const r = i % 2 === 0 ? radius : inner;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function label(value, x, y, size, color, maxWidth, weight) {
    const str = String(value);
    let fitted = size;
    const family = 'Arial, "DejaVu Sans", Helvetica, sans-serif';
    ctx.font = (weight || '700') + ' ' + fitted + 'px ' + family;
    const measured = ctx.measureText(str).width;
    if (maxWidth && measured > maxWidth) {
      fitted *= maxWidth / measured;
      ctx.font = (weight || '700') + ' ' + fitted + 'px ' + family;
    }
    const m = ctx.measureText(str);
    const ascent = m.actualBoundingBoxAscent || fitted * 0.73;
    const descent = m.actualBoundingBoxDescent || 0;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color;
    ctx.fillText(str, x, y + (ascent - descent) * 0.5);
  }

  // ---------------------------------------------------------------------
  // Shared toast clock (10 s cycle). Glasses and fireworks read from it.
  // ---------------------------------------------------------------------
  const cycle = loopT % 10;
  const approach = ease(0.7, 3.6, cycle) * (1 - ease(4.6, 8.9, cycle));

  const RIPPLE = 0.0009;   // seconds of burst delay per px from the centre
  const CLINK_AT = 3.62;   // glass contact moment
  const RISE = 2.0;        // rocket flight time before the burst
  const PALETTE = [C.gold, C.paleGold, C.ivory, C.coral];

  // Deterministic pseudo-random in [0, 1): same value every frame.
  const rnd = (n) => {
    const v = Math.sin(n * 127.1 + 311.7) * 43758.5453;
    return v - Math.floor(v);
  };
  const outCubic = (v) => 1 - Math.pow(1 - clamp(v), 3);

  // One firework: rocket -> burst -> droop -> crackle pops -> gone.
  //  cx, cy  : burst centre      size : master size (everything scales)
  //  side    : -1 / +1 mirror    seed : particle pattern (shared by a pair)
  //  launchY : where the rocket starts
  function firework(cx, cy, size, side, seed, launchY) {
    const delay = Math.abs(cx) * RIPPLE;
    const tb = CLINK_AT + delay;
    const life = 2.4 + size * 0.016;
    const lineW = Math.max(2.5, size * 0.035);

    // Rocket: eased climb that curves slightly toward the burst point.
    const rx = (e) => cx + side * size * 0.35 * (1 - e);
    const ry = (e) => launchY + (cy - launchY) * e;
    if (cycle >= tb - RISE && cycle < tb) {
      const q = (cycle - (tb - RISE)) / RISE;
      const e = outCubic(q);
      const et = outCubic(Math.max(0, q - 0.14));
      line(rx(et), ry(et), rx(e), ry(e), C.gold, lineW);
      ellipse(rx(e), ry(e), lineW * 0.9, lineW * 0.9, C.paleGold);
      for (let i = 1; i <= 4; i++) {
        const f = outCubic(Math.max(0, q - 0.14 - i * 0.04));
        const jx = (rnd(seed * 7 + i) - 0.5) * size * 0.08;
        const rr = lineW * (0.75 - i * 0.14);
        ellipse(rx(f) + jx, ry(f), rr, rr, C.ivory);
      }
    }

    if (cycle < tb || cycle >= tb + life) return;
    const p = (cycle - tb) / life;
    const droopAt = (pp) => size * 0.9 * pp * pp;
    const fade = 1 - ease(0.55, 1, p);

    // Burst particles: two concentric rings, streaks that become embers.
    const N = Math.round(size / 6) + 10;
    for (let ring = 0; ring < 2; ring++) {
      const n = ring ? Math.round(N * 0.6) : N;
      const ringScale = ring ? 0.55 : 1;
      for (let k = 0; k < n; k++) {
        const id = seed * 100 + ring * 50 + k;
        const a = TAU * (k + ring * 0.5) / n + (rnd(id) - 0.5) * 0.18;
        const sp = ringScale * (0.88 + 0.24 * rnd(id + 7));
        const dx = side * Math.cos(a);
        const dy = Math.sin(a);
        const posAt = (pp) => {
          const d = size * sp * outCubic(pp * 1.25);
          return [cx + dx * d, cy + dy * d + droopAt(pp)];
        };
        const cur = posAt(p);
        const prev = posAt(Math.max(0, p - 0.05));
        const color = PALETTE[(k + seed + ring) % PALETTE.length];
        const w = lineW * 1.1 * fade;
        if (p > 0.62 && Math.sin(p * 70 + id * 2.3) < -0.2) continue;
        if (w > 0.2) {
          line(prev[0], prev[1], cur[0], cur[1], color, w);
          ellipse(cur[0], cur[1], w * 0.85, w * 0.85, color);
        }
        if (ring === 0 && k % 5 === 0 && fade > 0.1) {
          star(cur[0], cur[1], size * 0.075 * fade, size * 0.03 * fade,
            4, a, color);
        }
      }
    }

    // Opening pop: solid flash star and a thin expanding ring.
    if (p < 0.1) {
      const q = 1 - p / 0.1;
      star(cx, cy, size * 0.45 * q, size * 0.12 * q, 8, 0, C.ivory);
    }
    if (p < 0.25) {
      const q = p / 0.25;
      const rr = size * 0.5 * outCubic(q);
      const lw = lineW * (1 - q);
      if (lw > 0.1) ellipse(cx, cy, rr, rr, null, C.paleGold, lw);
    }

    // Firecracker crackle: small stars snap at fixed spots around the burst.
    for (let m = 0; m < 5; m++) {
      const tp = 0.5 + m * 0.3;
      const dur = 0.38;
      const u = (cycle - tb - tp) / dur;
      if (u <= 0 || u >= 1) continue;
      const ang = rnd(seed * 13 + m) * TAU;
      const rad = size * (0.25 + 0.75 * rnd(seed * 17 + m));
      const pc = clamp((tp + u * dur) / life);
      const x = cx + side * Math.cos(ang) * rad;
      const y = cy + Math.sin(ang) * rad + droopAt(pc);
      const grow = ease(0, 0.25, u) * (1 - ease(0.25, 1, u));
      const r = size * 0.11 * grow;
      const color = PALETTE[(m + seed) % PALETTE.length];
      if (r > 0.2) star(x, y, r, r * 0.38, 4, m * 0.4, color);
      const tw = Math.max(1.5, size * 0.025) * (1 - u);
      for (let j = 0; j < 4; j++) {
        const ta = Math.PI / 4 + j * Math.PI / 2;
        const r1 = size * 0.11 * 1.5;
        const r2 = r1 + size * 0.09 * u;
        line(x + Math.cos(ta) * r1, y + Math.sin(ta) * r1,
          x + Math.cos(ta) * r2, y + Math.sin(ta) * r2, color, tw);
      }
    }
  }

  // A stable header; its side accents are now small firework launchers.
  rounded(-389, -449, 778, 74, 37, C.navy);
  rounded(-376, -437, 752, 50, 25, null, C.gold, 2);
  label('HAPPY NEW YEAR', 0, -412, 35, C.ivory, 630);

  // Tray and caption.
  ellipse(0, 359, 548, 25, C.navy);
  ellipse(0, 354, 528, 17, C.paper);
  ctx.beginPath();
  ctx.ellipse(0, 354, 493, 11, 0, 0.13, Math.PI - 0.13);
  ctx.strokeStyle = C.gold;
  ctx.lineWidth = 3;
  ctx.stroke();
  rounded(-325, 408, 650, 63, 30, C.navy);
  label('CHEERS TO NEW BEGINNINGS', 0, 440, 25, C.ivory, 568);

  // Four mirrored firework pairs, large to small, clear of glasses/header.
  for (let side = -1; side <= 1; side += 2) {
    firework(side * 690, -235, 105, side, 1, 330);   // big, upper
    firework(side * 640, 30, 80, side, 2, 330);      // medium, middle
    firework(side * 635, 215, 58, side, 3, 330);     // small, lower
    firework(side * 470, -410, 38, side, 4, -250);   // mini, header
  }

  const tilt = 0.15 * approach;
  const rimSupport = Math.sqrt(
    Math.pow(72 * Math.cos(tilt), 2) + Math.pow(11 * Math.sin(tilt), 2)
  );
  const contactDistance = 430 * Math.sin(tilt) + rimSupport;
  const distance = contactDistance + (350 - contactDistance) * (1 - approach);
  const baseY = 333 - 218 * approach;
  const contactY = baseY - 430 * Math.cos(tilt)
    + (72 * 72 - 11 * 11) * Math.sin(tilt) * Math.cos(tilt) / rimSupport;

  // Only small solid clink marks appear, well clear of the header and rims.
  const clink = ease(3.6, 3.8, cycle) * (1 - ease(4.15, 4.55, cycle));
  if (clink > 0) {
    for (let i = 0; i < 3; i++) {
      const a = -Math.PI / 2 + (i - 1) * 0.66;
      const r1 = 23;
      const r2 = r1 + 14 * clink;
      line(Math.cos(a) * r1, contactY + Math.sin(a) * r1,
        Math.cos(a) * r2, contactY + Math.sin(a) * r2,
        C.gold, 3.5 * clink);
    }
  }

  function drawBottle() {
    // A generic, original bottle without a brand or external artwork.
    ctx.save();
    ctx.translate(0, 346);
    ctx.scale(1.28, 1.28);
    ctx.translate(0, -346);
    ellipse(0, 345, 65, 9, C.navy);
    ctx.beginPath();
    ctx.moveTo(-28, 132);
    ctx.lineTo(-28, 188);
    ctx.bezierCurveTo(-29, 202, -79, 205, -92, 240);
    ctx.lineTo(-92, 323);
    ctx.quadraticCurveTo(-92, 346, -68, 346);
    ctx.lineTo(68, 346);
    ctx.quadraticCurveTo(92, 346, 92, 323);
    ctx.lineTo(92, 240);
    ctx.bezierCurveTo(79, 205, 29, 202, 28, 188);
    ctx.lineTo(28, 132);
    ctx.closePath();
    ctx.fillStyle = C.navy;
    ctx.fill();
    rounded(-18, 140, 36, 43, 8, C.blue);
    line(-10, 149, 10, 149, C.gold, 3);
    line(-10, 169, 10, 169, C.gold, 3);
    ctx.beginPath();
    ctx.moveTo(-64, 224);
    ctx.bezierCurveTo(-49, 213, -34, 207, -26, 199);
    ctx.strokeStyle = C.blue;
    ctx.lineWidth = 7;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(64, 224);
    ctx.bezierCurveTo(49, 213, 34, 207, 26, 199);
    ctx.stroke();
    rounded(-78, 237, 156, 94, 17, C.blue);
    rounded(-68, 226, 136, 95, 14, C.ivory);
    line(-52, 239, 52, 239, C.gold, 2);
    star(0, 259, 12, 5, 5, -Math.PI / 2, C.gold);
    label('CHEERS', 0, 284, 22, C.navy, 116);
    label('NEW YEAR', 0, 307, 11, C.blue, 106, '600');
    rounded(-37, 106, 74, 33, 10, C.navy);
    rounded(-30, 112, 60, 21, 6, C.gold);
    line(-21, 122, 21, 122, C.navy, 2);
    ctx.restore();
  }

  function bowlPath(inner) {
    ctx.beginPath();
    if (inner) {
      ctx.moveTo(-63, -428);
      ctx.lineTo(-54, -282);
      ctx.bezierCurveTo(-49, -235, -31, -207, 0, -207);
      ctx.bezierCurveTo(31, -207, 49, -235, 54, -282);
      ctx.lineTo(63, -428);
    } else {
      ctx.moveTo(-72, -430);
      ctx.lineTo(-62, -280);
      ctx.bezierCurveTo(-57, -228, -37, -198, 0, -198);
      ctx.bezierCurveTo(37, -198, 57, -228, 62, -280);
      ctx.lineTo(72, -430);
    }
    ctx.closePath();
  }

  function drawGlass(x, y, angle, side) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ellipse(0, 0, 65, 13, C.navy);
    ellipse(0, -3, 53, 6, C.glass);
    rounded(-7, -202, 14, 195, 5, C.navy);
    line(0, -190, 0, -14, C.ivory, 5);
    bowlPath(false);
    ctx.fillStyle = C.navy;
    ctx.fill();
    bowlPath(true);
    ctx.fillStyle = C.glass;
    ctx.fill();

    // Unrotate only the liquid drawing coordinates inside a fixed bowl clip.
    // The opaque liquid surface remains level while the glass tilts.
    ctx.save();
    bowlPath(true);
    ctx.clip();
    ctx.rotate(-angle);
    const level = -330 * Math.cos(angle);
    ctx.fillStyle = C.amber;
    ctx.fillRect(-140, level, 280, 185);
    ctx.fillStyle = C.gold;
    ctx.fillRect(-140, level, 280, 13);
    line(-140, level + 2, 140, level + 2, C.paleGold, 3);

    for (let i = 0; i < 7; i++) {
      const q = ((loopT / 5) + i * 0.173 + (side > 0 ? 0.08 : 0)) % 1;
      const grow = ease(0, 0.15, q) * (1 - ease(0.8, 1, q));
      const bx = [-22, 17, -9, 28, 3, -30, 12][i];
      const by = -220 - 96 * q;
      const r = (2.2 + (i % 3) * 0.45) * grow;
      if (r > 0.01) ellipse(bx, by, r, r, C.paleGold);
    }
    ctx.restore();

    // These are flat material highlights, not light or transparency effects.
    line(-44, -400, -39, -354, C.ivory, 7);
    line(45, -393, 43, -370, C.ivory, 4);
    ellipse(0, -430, 72, 11, C.navy);
    ellipse(0, -432, 62, 5, C.ivory);
    ctx.restore();
  }

  // The rim support calculation gives exact exterior tangency at contact.
  // At all other poses there is a positive gap between the glass silhouettes.
  drawBottle();
  drawGlass(-distance, baseY, tilt, -1);
  drawGlass(distance, baseY, -tilt, 1);

  ctx.restore();
}

/*
 * NEW YEAR 04 — NEW YEAR FIREWORKS CITYSCAPE
 * Pure Canvas 2D, no assets, no dependencies, no glow.
 * One 20-second scene; individually timed vector fireworks; seamless loop.
 * Host export preset: 3840x2160, 60 fps, 100,000,000 bps minimum.
 * The drawing function does not configure the host video encoder.
 */

function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (sceneProgress + currentScene);
  const C = {
    navy: '#172442',
    blue: '#294B91',
    deepBlue: '#213661',
    ivory: '#FFF7E6',
    paper: '#F4E7CB',
    gold: '#E9B454',
    paleGold: '#F9D78C',
    coral: '#E97870',
    mauve: '#AC78A8'
  };
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (a, b, v) => {
    const q = clamp((v - a) / (b - a));
    return q * q * q * (q * (q * 6 - 15) + 10);
  };

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent';
  ctx.filter = 'none';
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function rounded(x, y, w, h, radius, color, stroke, lineWidth) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (color) { ctx.fillStyle = color; ctx.fill(); }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = lineWidth || 3;
      ctx.stroke();
    }
  }

  function circle(x, y, r, color) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function line(x1, y1, x2, y2, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function star(x, y, radius, inner, points, angle, color) {
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const a = angle + i * Math.PI / points;
      const r = i % 2 === 0 ? radius : inner;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function label(value, x, y, size, color, maxWidth, weight) {
    const str = String(value);
    let fitted = size;
    const family = 'Arial, "DejaVu Sans", Helvetica, sans-serif';
    ctx.font = (weight || '700') + ' ' + fitted + 'px ' + family;
    const measured = ctx.measureText(str).width;
    if (maxWidth && measured > maxWidth) {
      fitted *= maxWidth / measured;
      ctx.font = (weight || '700') + ' ' + fitted + 'px ' + family;
    }
    const m = ctx.measureText(str);
    const ascent = m.actualBoundingBoxAscent || fitted * 0.73;
    const descent = m.actualBoundingBoxDescent || 0;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color;
    ctx.fillText(str, x, y + (ascent - descent) * 0.5);
  }

  // All lettering and decorative stars lie outside the firework corridors.
  rounded(-389, -449, 778, 74, 37, C.navy);
  rounded(-376, -437, 752, 50, 25, null, C.gold, 2);
  label('NEW YEAR CELEBRATION', 0, -412, 30, C.ivory, 672);
  for (let side = -1; side <= 1; side += 2) {
    star(side * 443, -412, 14, 5, 4, -Math.PI / 2 + phase, C.gold);
    line(side * 485, -412, side * 525, -412, C.navy, 4);
    star(side * 763, -212 + 3 * Math.sin(phase), 13, 5, 4,
      -Math.PI / 2 + 0.08 * Math.sin(phase), C.gold);
    circle(side * 787, -300, 5, C.coral);
    line(side * 729, -337, side * 745, -345, C.navy, 3.5);
  }
  rounded(-354, 392, 708, 62, 30, C.navy);
  label('CELEBRATE A NEW BEGINNING', 0, 423, 25, C.ivory, 636);
  for (let side = -1; side <= 1; side += 2) {
    const bob = 3 * Math.sin(phase * 2 + side);
    star(side * 474, 422 + bob, 12, 4.5, 4, -Math.PI / 2, C.gold);
    line(side * 523, 423, side * 583, 423, C.navy, 4);
    circle(side * 633, 423 - bob, 5, C.coral);
  }

  function windowColor(v) {
    // An opaque navy-to-warm-gold mix; no alpha or artificial light effects.
    const r = Math.round(23 + (249 - 23) * v);
    const g = Math.round(36 + (215 - 36) * v);
    const b = Math.round(66 + (140 - 66) * v);
    return 'rgb(' + r + ',' + g + ',' + b + ')';
  }

  function building(x, w, h, columns, rows, color, index, antenna) {
    const base = 306;
    const y = base - h;
    rounded(x, y, w, h, 12, C.navy);
    rounded(x + 8, y + 9, w - 16, h - 17, 7, color);
    rounded(x - 6, y - 12, w + 12, 24, 7, C.navy);
    rounded(x + 1, y - 6, w - 2, 8, 3, C.gold);
    if (antenna) {
      const cx = x + w * 0.5;
      line(cx, y - 12, cx, y - 46, C.navy, 5);
      circle(cx, y - 49, 5, C.gold);
      line(cx - 14, y - 27, cx + 14, y - 27, C.navy, 3);
    }
    const gap = 12;
    const windowW = (w - 36 - (columns - 1) * gap) / columns;
    const windowH = 24;
    const rowGap = (h - 96 - rows * windowH) / (rows - 1);
    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < columns; col++) {
        const wx = x + 18 + col * (windowW + gap);
        const wy = y + 44 + row * (windowH + rowGap);
        const wave = 0.5 + 0.5 * Math.sin(
          phase * 2 + index * 0.73 + col * 0.65 - row * 0.43
        );
        const fixedBright = (row + col + index) % 4 === 0;
        const v = fixedBright ? 0.92 : 0.35 + 0.45 * wave;
        rounded(wx - 2, wy - 2, windowW + 4, windowH + 4, 4, C.navy);
        rounded(wx, wy, windowW, windowH, 2, windowColor(v));
        if (columns <= 3) line(wx + windowW * 0.5, wy + 2,
          wx + windowW * 0.5, wy + windowH - 2, C.navy, 2);
      }
    }
    const doorX = x + w * 0.5 - 15;
    rounded(doorX, base - 43, 30, 34, 5, C.navy);
    line(doorX + 15, base - 39, doorX + 15, base - 13, C.gold, 2);
    line(x + 12, base - 6, x + w - 12, base - 6, C.gold, 3);
  }

  function drawCity() {
    // Each building is seated six pixels into its common foundation.
    rounded(-780, 300, 1560, 61, 22, C.navy);
    rounded(-764, 300, 1528, 11, 5, C.gold);
    label('MIDNIGHT IN THE CITY', 0, 337, 21, C.ivory, 532, '600');
    line(-691, 337, -383, 337, C.blue, 3);
    line(383, 337, 691, 337, C.blue, 3);

    // Roofs, antennas and window grids retain clear separations at all times.
    building(-742, 142, 205, 3, 3, C.coral, 0, false);
    building(-566, 160, 271, 3, 4, C.ivory, 1, false);
    building(-372, 158, 328, 3, 5, C.blue, 2, true);
    building(214, 158, 316, 3, 5, C.blue, 3, true);
    building(406, 160, 254, 3, 4, C.ivory, 4, false);
    building(600, 142, 198, 3, 3, C.coral, 5, false);

    rounded(-158, 101, 316, 205, 18, C.navy);
    rounded(-146, 113, 292, 183, 10, C.ivory);
    rounded(-178, 73, 356, 41, 12, C.navy);
    rounded(-167, 81, 334, 8, 4, C.gold);
    for (let i = 0; i < 11; i++) circle(-145 + 29 * i, 101, 3, C.paleGold);
    label('HAPPY', 0, 155, 28, C.blue, 236);
    label('NEW YEAR', 0, 207, 44, C.navy, 260);
    line(-100, 237, 100, 237, C.gold, 2.5);
    star(0, 266, 15, 6.5, 5, -Math.PI / 2, C.gold);
  }

  function drawBurst(event) {
    const age = (loopT - event.start + duration) % duration;
    if (age >= event.life) return;
    const launchTime = event.small ? 0.65 : 0.9;
    const launchProgress = clamp(age / launchTime);
    const launchEase = 1 - Math.pow(1 - launchProgress, 3);
    const launchY = -100 + (event.y + 100) * launchEase;
    const launchSize = ease(0, 0.12, age)
      * (1 - ease(launchTime - 0.12, launchTime + 0.03, age));
    if (launchSize > 0.001) {
      const head = 3.2 * launchSize;
      rounded(event.x - head, launchY - 6 * launchSize,
        head * 2, 12 * launchSize, head, C.gold);
      line(event.x, launchY + 13, event.x, launchY + 24,
        C.coral, 2.5 * launchSize);
      line(event.x, launchY + 30, event.x, launchY + 36,
        C.gold, 2 * launchSize);
    }
    if (age < launchTime) return;
    const p = (age - launchTime) / (event.life - launchTime);
    const envelope = ease(0, 0.09, p) * (1 - ease(0.62, 1, p));
    if (envelope <= 0.00001) return;
    const count = event.small ? 13 : event.kind === 'flower' ? 26 : 22;
    const seedBase = Math.round(event.start * 100) + (event.x + 800) * 3;

    // Each spark has its own speed, drag and fall. Its curved tail follows the
    // same trajectory as its head, creating an ordinary expanding firework.
    for (let i = 0; i < count; i++) {
      const seed = (((i + 1) * 37 + seedBase) % 101 + 101) % 101;
      const h1 = seed / 100;
      const h2 = ((seed * 31 + 17) % 101) / 100;
      const h3 = ((seed * 53 + 29) % 101) / 100;
      const speed = (0.56 + 0.44 * h1)
        * (event.kind === 'flower' && i % 4 === 0 ? 0.77 : 1);
      const drag = 2.2 + 0.8 * h2;
      const fall = (event.small ? 32 : 43) * (0.8 + 0.35 * h3);
      const jitter = (h2 - 0.5) * 0.09;
      const a = event.kind === 'fan'
        ? -Math.PI + 0.16 + i * (Math.PI - 0.32) / (count - 1) + jitter
        : -Math.PI / 2 + i * TAU / count + jitter;
      const ca = Math.cos(a);
      const sa = Math.sin(a);
      const travelScale = event.radius * speed / (1 - Math.exp(-drag));
      const tailSpan = 0.20 + 0.07 * h3;
      const startP = Math.max(0.018, p - tailSpan);
      const tailStart = Math.min(startP, p);
      const midP = (tailStart + p) * 0.5;
      const r0 = travelScale * (1 - Math.exp(-drag * tailStart));
      const rm = travelScale * (1 - Math.exp(-drag * midP));
      const r1 = travelScale * (1 - Math.exp(-drag * p));
      const x0 = event.x + ca * r0;
      const y0 = event.y + sa * r0 + fall * tailStart * tailStart;
      const xm = event.x + ca * rm;
      const ym = event.y + sa * rm + fall * midP * midP;
      const x1 = event.x + ca * r1;
      const y1 = event.y + sa * r1 + fall * p * p;
      const color = [C.gold, C.coral, C.ivory, C.mauve][i % 4];
      const weight = (0.76 + 0.24 * h2) * envelope;

      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.quadraticCurveTo(2 * xm - (x0 + x1) * 0.5,
        2 * ym - (y0 + y1) * 0.5, x1, y1);
      ctx.strokeStyle = color;
      ctx.lineWidth = (event.small ? 2.4 : 3.3) * weight;
      ctx.stroke();
      circle(x1, y1, (event.small ? 1.8 : 2.5) * weight, color);
    }
  }

  function drawFireworks() {
    // Periodic event ages carry the final launch and burst smoothly into t = 0.
    // Primary zones are 560 px apart; satellites have their own smaller lanes.
    const events = [
