  const C = {
    navy: '#172442',
    blue: '#294B91',
    deepBlue: '#213661',
    ivory: '#FFF7E6',
    paper: '#F5E8CD',
    gold: '#E9B454',
    paleGold: '#F9D78C',
    coral: '#E97870',
    mauve: '#AC78A8'
  };

  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (a, b, v) => {
    const q = clamp((v - a) / (b - a));
    return q * q * q * (q * (q * 6 - 15) + 10);
  };

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
