    for (let j = 0; j < 3; j++) {
      const a = -Math.PI * 0.5 + side * (0.62 + j * 0.28);
      const r = 57 + j * 8;
      line(cx + Math.cos(a) * r, cy + Math.sin(a) * r,
        cx + Math.cos(a) * (r + 11), cy + Math.sin(a) * (r + 11),
        j === 1 ? C.coral : C.navy, 4);
    }
    for (let burst = 0; burst < 2; burst++) {
      const start = 11.25 + burst * 2.75 + (side > 0 ? 0.18 : 0);
      const p = (loopT - start) / 2.15;
      if (p <= 0 || p >= 1) continue;
      const envelope = ease(0, 0.13, p) * (1 - ease(0.72, 1, p));
      for (let i = 0; i < 12; i++) {
        const a = -Math.PI + i * TAU / 12 + burst * 0.19;
        const travel = 39 + 52 * (1 - Math.pow(1 - p, 2));
        const px = cx + Math.cos(a) * travel;
        const py = cy + Math.sin(a) * travel + 16 * p * p;
