  label('A NEW BEGINNING', 0, 379, 27, C.ivory, 594);
  for (let side = -1; side <= 1; side += 2) {
    circle(side * 326, 378, 6, C.gold);
    line(side * 350, 383, side * 350, 372, C.ivory, 3);
  }

  // Two date capsules, with clear corridors around the central case.
  for (let side = -1; side <= 1; side += 2) {
